WITH 均值 AS (
    SELECT AVG(年度开单金额) AS 平均开单 FROM v_angel_group_data WHERE 分公司 = "东部分公司" AND 代表处 IS NOT NULL
)
SELECT 代表处, 年度开单金额, ROUND(年度开单金额 - 均值.平均开单, 2) AS 差距
FROM v_angel_group_data, 均值
WHERE 代表处 = "上海代表处";

SELECT '电商业务' AS 条线, 层级级别 AS 层级, COALESCE(NULLIF(TRIM(细分业务), ''), NULLIF(TRIM(业务部), ''), '电商事业部') AS 节点名称, 业务部 AS 上级名称, 年度目标营收 AS 总任务金额, 年度开单金额, NULLIF(TRIM(负责人), '') AS 业务承接人, ROUND(总任务达成率 * 100, 2) AS 达成率, ROUND(年度目标营收 - 年度开单金额, 2) AS 剩余任务金额
